from model import *
c=C(13,'检查单模块详细设计','第二篇  分模块详细设计')
S(c,'检查单定义与运行记录',
P('内容定义和完成状态分离','''检查单内容由机型资料提供，运行记录由 trackingChecklists 保存。aircraftChecklists 包含名称、阶段及条目定义；checklists 保存对应条目的 completed、hasCondition 和整单 markedCompleted。定义描述“检查什么”，运行记录描述“本次进行到哪里”。

两组数组按检查单索引和条目索引对应。初始化必须先加载定义，再按相同顺序创建运行记录，否则页面可能把另一条目的状态显示在当前文字旁。索引关联适合固定配置，但配置更新时不能直接沿用旧索引状态。

selectedChecklistIndex 只决定当前显示哪一张清单，不代表已经进入相应飞行阶段，也不自动完成此前的清单。''',diagram=D('entity','定义、跟踪记录与当前选择',[['Checklist 定义','name / flightphase','items[]','文字及 condition'],['TrackingChecklist','name / items[]','completed / hasCondition','markedCompleted'],['当前选择','selectedChecklistIndex','条目组件','完成按钮']],[(0,1,'按相同索引初始化'),(1,2,'提供运行状态')]),table=T('信息|是否为内容定义|改变时机','条目名称和动作文字|是|机型资料更新\n自动判断条件|是|机型资料更新\n条目完成状态|否|点击或自动判断\n整单确认|否|用户完成整单\n当前选择|否|导航切换')),
P('条目类型与表现规则','''定义支持普通条目、子条目、分隔线和子列表标题。普通条目与子条目具有检查含义，分隔线和标题负责组织版面。条目组件按 type 决定缩进、勾选框和文字布局，而不是把每一行都当成可点击任务。

未完成条目优先显示 action，完成后显示 result。例如检查前的动作词与检查后的结果词可以不同，帮助用户理解状态变化。已完成条目变为绿色，顺序上出现遗漏时可用红色提示。

分隔线不可点击。自动状态更新还将分隔线和子标题视为完成，避免它们阻碍整张清单的完成比例。这是版面项与业务项共存时的处理约定。''',diagram=D('tree','检查单条目类型',['Checklist.items',['ITEM','主要检查项目','动作与结果文字'],['SUBLISTITEM','从属项目','缩进表达关系'],['结构行','LINE 分隔线','SUBLISTHEADER 标题']]),table=T('条目类型|可见作用|完成含义','ITEM|主要项目|具有业务状态\nSUBLISTITEM|细分项目|具有业务状态\nLINE|分段|不要求用户检查\nSUBLISTHEADER|说明分组|不作为独立检查动作')),
P('完成比例与整单确认','''getChecklistCompletion 将已完成条目数除以总条目数，areAllChecklistItemsCompleted 判断该值是否等于 1。markedCompleted 是另一个布尔状态，只有明确完成整单后才设置。全部条目完成时，清单仍可能处于等待整单确认状态。

这种设计保留最后的人工收束动作。用户可以看到条目已经满足，同时决定是否结束本张清单并继续下一张。界面用不同状态颜色区分“条目齐全”和“已经确认”。

若用户撤销一个已完成条目，组件同时撤销 markedCompleted，避免整单继续显示已确认但其中又有未完成项目。''',diagram=D('state','条目完成与整单确认的两级状态',['部分条目完成','全部条目完成','整单已确认','下一张清单'],[(0,1,'完成剩余条目'),(1,2,'确认整单'),(2,3,'继续下一张'),(2,0,'撤销某条目')]),table=T('全部条目 completed|markedCompleted|语义','false|false|检查进行中\ntrue|false|等待整单确认\ntrue|true|本单已完成\n撤销条目后|重置为 false|重新检查')) ,refs=['EFB','CHK'])
S(c,'自动判断与人工确认',
P('条件表达与比较器','''自动条目包含 condition 数组，每个条件具有变量名、比较符和目标值。setAutomaticItemStates 从 SimVar 读取 Number，按 NE、LT、LE、EQ、GE、GT 执行比较；缺少比较符时默认 EQ。多个条件采用 every，即全部满足才算完成。

未知比较符返回 false 并记录警告，不把无法解释的规则当作通过。没有条件的业务条目由人工处理，自动更新器直接略过。这样规则驱动与人工确认可以在一张清单中并存。

数字比较依赖宿主变量的真实含义和类型。浏览器默认值零可能偶然满足某个 EQ 0 条件，因此演示中的自动勾选不能被当作真实飞机状态证据。''',diagram=D('pipeline','自动条目的条件求值',['取得条目条件','读取各 SimVar','按比较符判断','对条件执行 every','更新 completed','页面显示状态']),table=T('比较符|关系|默认行为','EQ / NE|等于 / 不等于|未指定时使用 EQ\nLT / LE|小于 / 小于等于|数字比较\nGT / GE|大于 / 大于等于|数字比较\n未知值|无法解释|返回 false')),
P('刷新周期与已完成清单','''自动状态更新由 EFB 定期调用，并在切换选中清单时重新触发。选项 EFB_AUTOFILL_CHECKLISTS 控制是否启用自动填写。已 markedCompleted 的清单被跳过，避免后来设备状态变化把已经确认的历史清单反复重置。

未确认清单中的条件条目仍可随变量变化从完成变回未完成。这个变化表示当前条件不再成立，与用户手工撤销有不同来源，但对条目最终状态具有相同显示效果。

该机制让“当前检查状态”和“已确认检查记录”具有不同稳定性。它不是完整审计日志：状态只保存当前结果，没有为每次自动变化记录不可修改的时间序列。''',diagram=D('sequence','自动条件刷新保留已确认清单',['定时更新','运行记录','SimVar 条件','Store'],[(0,1,'遍历清单'),(1,1,'已确认则跳过'),(1,2,'未确认条目求值'),(2,3,'写入 completed'),(3,0,'下次周期继续')]),table=T('清单状态|自动变量变化|处理','未确认且有条件|变化|重新判断条目\n未确认且无条件|变化|人工状态保持\n整单已确认|变化|跳过自动更新\n自动选项关闭|任意|使用人工流程')),
P('人工动作与条件条目的协调','''普通条目点击后反转 completed。自动填写开启且条目处于自动判断范围时，条件条目不接受手工反转，而以抖动和提示说明其状态来自条件。连续触碰自动条目三次会显示说明消息。

完成按钮寻找第一个尚未完成的人工条目。自动填写开启时，带条件的项目从这个人工搜索中排除；当仅剩自动条目未满足时，按钮不能通过一次点击强行完成它们。

这种交互减少人工与自动两种来源争夺同一状态。使用手工演示时，可以在 Realism 中关闭自动填写，随后按普通清单逐项确认。''',diagram=D('components','人工点击由条目性质和模式决定',['用户点击','自动填写选项','条目条件','交互判断','切换人工状态','显示条件说明'],[(0,3,'动作'),(1,3,'当前模式'),(2,3,'条目类型'),(3,4,'可手工完成'),(3,5,'由条件控制')]),table=T('条目|自动填写关闭|自动填写开启且可自动判断','无 condition|点击切换|点击切换\n有 condition|按人工方式处理|由宿主条件控制\n分隔线|不响应|不响应')) ,refs=['EFB','CHK','SET'])
S(c,'阶段关联、复位与入口协同',
P('飞行阶段的相关性选择','''getRelevantChecklistIndices 读取 L:A32NX_FWC_FLIGHT_PHASE，将定义中 flightphase 不大于当前阶段的清单视为相关。列表中第一个相关且尚未 markedCompleted 的清单用于自动流程提示。

这种相关性不是强制导航锁。用户仍可以选择其他清单查看内容，但系统提示会帮助定位尚未结束的阶段。飞行阶段值由宿主提供，本地航班确认并不直接驱动完整 FWC 阶段机。

阶段数字在不同系统中不能只凭数值复用。外部宿主需要明确把自身飞行阶段映射为当前检查单期待的阶段定义，避免同一个数字在不同系统中表达不同含义。''',diagram=D('pipeline','相关清单从宿主阶段筛选',['读取 FWC 阶段','遍历机型清单','比较 flightphase','得到相关索引','寻找首个未确认项','显示流程提示']),table=T('数据|承担的含义|不承担的含义','flightphase|清单适用阶段|强制用户已完成该阶段\n当前宿主阶段|相关性依据|本地航班文件状态\n相关索引集合|候选清单|自动全部勾选\n首个未确认项|引导位置|完整流程审批')),
P('统一完成入口与外设变量','''CompletionButton 依次处理三个动作：完成当前首个未完成条目、确认整张清单、在整单确认后进入下一张。最后一张已完成时显示结束信息，不再增加无效索引。

原生实现还监听 L:A32NX_EFB_CHECKLIST_COMPLETE_ITEM。变量变为 true 时先将其重置为 false，再执行与完成按钮对应的动作，形成一次触发一次消费的脉冲语义。它可以作为硬件按键的接口入口。

浏览器中保留该接口并不意味着已有外接硬件。真实接入时，应控制按键重复触发和反馈节奏，避免一次长按产生多次跨条目完成。''',diagram=D('state','同一完成入口随进度改变含义',['有人工条目未完成','条目已全部完成','整单已确认','最后一单已确认'],[(0,0,'完成首个条目'),(0,1,'剩余条目完成'),(1,2,'确认整单'),(2,0,'进入下一张'),(2,3,'已是最后一张')]),table=T('入口状态|一次点击的含义|反馈','有未完成人工项|完成首项|项目状态改变\n全部条目完成|确认整单|整单状态改变\n整单已确认|进入下一张|选中索引改变\n最后一单完成|显示结束|保持当前页')),
P('单张与全部复位','''复位当前清单清除对应的人工条目完成状态，并把整单 markedCompleted 置为 false。全部复位对每张清单重复这一过程，并先显示确认对话框，防止误触丢失整套检查进度。

自动填写开启时，带条件项目不由复位动作强制改为 false，而保留给自动条件判断处理。因此复位后仍看到某些条件项完成，属于模式定义，并不意味着复位按钮没有响应。

复位与新建本地航班没有隐式等价关系。当前各模块状态分开保存，用户开始另一场演示时应按需要重置检查单，而不能假设更改航班号就清空所有原生页面进度。''',diagram=D('sequence','全部复位的显式确认流程',['用户','确认对话框','检查单 Store','自动判断器'],[(0,1,'点击全部复位'),(1,2,'确认后清除人工状态'),(2,2,'markedCompleted = false'),(3,2,'条件项按变量求值'),(2,0,'显示新的进度')]),table=T('操作|影响范围|条件项目','当前清单复位|选中清单|自动模式时保留条件控制\n全部复位|全部清单|相同规则\n新建航班|本地 Flight|不是检查单复位命令')),
P('与仪表盘和本地流程衔接','''仪表盘提醒组件显示检查单进度并提供入口，本地结果页也可引导用户继续检查流程。入口共享的是同一 trackingChecklists 状态，而不是分别复制一套独立清单。

从计算页进入检查单只完成导航，不应自动勾选检查项目。参考计算完成与某项飞机检查通过没有直接等价关系；具体条目仍由用户或有效宿主条件确认。

在扩展运行记录设计中，可以为航班身份和检查单进度建立显式关联，并记录确认时间与来源。当前浏览器实现没有这套跨航班审计模型，因此说明书以现有状态和入口关系为准。''',diagram=D('components','多个入口共享同一检查单状态',['仪表盘提醒','本地结果页入口','检查单页面','trackingChecklists','机型定义'],[(0,2,'打开页面'),(1,2,'打开页面'),(3,0,'进度摘要'),(3,2,'条目状态'),(4,2,'显示内容')]),table=T('入口|共享内容|不会自动执行','仪表盘|当前进度|确认整单\n本地计算页|检查单路由|替用户勾选\n原生导航|完整检查页面|重置所有进度\n未来航班记录|需要新增身份关联|当前尚未实现')) ,refs=['EFB','CHK','L-U'])
